from pathlib import Path
import shutil

root=Path('.')
index=root/'dist'/'index.html'
if not index.exists(): raise SystemExit('dist/index.html not found')
for name in ('galactic-map-oskn-helios.png','custodes-med-b4.png'):
    src=root/'assets'/name
    if not src.exists(): raise SystemExit(f'missing asset: {src}')
    dst=root/'dist'/'assets'/name
    dst.parent.mkdir(parents=True,exist_ok=True)
    shutil.copy2(src,dst)
html=index.read_text(encoding='utf-8')

if '/* PRESS17 */' not in html:
    css='''\n/* PRESS17 */\n.news-article{grid-column:1/-1;background:linear-gradient(180deg,rgba(18,25,24,.97),rgba(8,12,11,.99));border:1px solid var(--line);padding:20px;position:relative}.news-article:before{content:"";position:absolute;left:0;top:0;width:64px;height:2px;background:var(--orange)}.news-article h3{font:700 clamp(22px,2.6vw,34px)/1.08 "Arial Narrow",Arial,sans-serif;margin:6px 0 12px;text-transform:uppercase;letter-spacing:.045em}.news-deck{color:#e7e8e3;font-size:13px;line-height:1.7;max-width:1100px;margin:0 0 16px}.news-body{columns:2;column-gap:34px;column-rule:1px solid #26332e}.news-body p{break-inside:avoid;margin:0 0 15px;color:#cbd1cd;font-size:12px;line-height:1.82}.news-body p:first-child:first-letter{float:left;font:700 42px/32px "Arial Narrow",Arial,sans-serif;color:var(--orange);padding:5px 7px 0 0}.news-image{margin:14px 0 20px;border:1px solid var(--line);background:#050706;position:relative;cursor:zoom-in}.news-image img{display:block;width:100%;height:auto!important;max-height:none!important;object-fit:contain!important;background:#050706}.press-meta{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}.press-meta span{border:1px solid #3b4a44;padding:5px 8px;color:#9fa9a4;font-size:9px;text-transform:uppercase;letter-spacing:.1em}.press-meta .hot{border-color:#6f5c31;color:var(--orange2)}.gallery-wall{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.gallery-tile{background:#0a0e0d;border:1px solid var(--line);padding:10px}.gallery-tile img{width:100%;height:auto;display:block;object-fit:contain;background:#050706;cursor:zoom-in}.gallery-tile h4{margin:10px 2px 5px;text-transform:uppercase;letter-spacing:.05em}.gallery-tile p{margin:0 2px 4px;color:var(--muted);font-size:10px;line-height:1.55}.press-index{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.press-link{display:block;border:1px solid var(--line);background:#0a0e0d;padding:13px;text-decoration:none}.press-link b{display:block;color:#e5e6e2;text-transform:uppercase;font-size:12px}.press-link small{display:block;color:var(--muted);margin-top:6px;line-height:1.5}.press-link:hover{border-color:#6f5c31;background:#111715}@media(max-width:900px){.news-body{columns:1}.gallery-wall,.press-index{grid-template-columns:1fr}}\n'''
    html=html.replace('</style>',css+'\n</style>',1)
html=html.replace('nav{display:grid;grid-template-columns:repeat(8,1fr);','nav{display:grid;grid-template-columns:repeat(9,1fr);',1)
html=html.replace('vrstva kánonu: ARGUS → NII → HELIOR → NEZNÁMÝ PROSTOR → MEZIRASOVÁ STANICE','vrstva kánonu: ARGUS → NII → HELIOR → PROTOS SINGULÁR → HELIOS → CUSTODES / RECENSIO')

def insert(section_id,fragment,marker):
    global html
    if marker in html:return
    p=html.find(f'id="{section_id}"')
    if p<0:raise SystemExit(f'section {section_id} not found')
    start=html.rfind('<section',0,p)
    nxt=html.find('<section',p+1)
    end=nxt if nxt>=0 else html.find('</main>',start)
    chunk=html[start:end]
    close=chunk.rfind('</div>')
    if close<0:raise SystemExit(f'grid close not found: {section_id}')
    pos=start+close
    html=html[:pos]+fragment+'\n'+html[pos:]

map_article='''
<article class="news-article" id="article-galactic-map"><span class="label green">speciální vydání // galaktická orientace</span><h3>Galaktická mapa: od jedné rezervní posádky k prostoru OSKN a spojenectví s HELIOSem</h3><p class="news-deck">Nová orientační mapa shrnuje největší změnu měřítka celého příběhu: cesta, která začala starou korvetou Argus a malou nouzovou posádkou, dnes vede přes Protos Singulár, A7 a diplomatický koridor NII až k mnohosvětové říši HELIOS a k oblastem, které zůstávají jen částečně prozkoumané.</p><div class="news-image lightbox"><img src="/assets/galactic-map-oskn-helios.png" alt="Galaktická mapa prostoru OSKN, říše HELIOSU a známých tras Vampirusu" loading="lazy"><span class="caption">GALAKTICKÁ MAPA // OSKN + HELIOS</span></div><div class="press-meta"><span class="hot">OSKN</span><span>HELIOS</span><span>Protos Singulár</span><span>A7</span><span>Vampirus</span><span>živý orientační dokument</span></div><div class="news-body">
<p>Nově zařazená galaktická mapa nepředstavuje absolutně přesný astrofyzikální atlas. Je to strategický a vyprávěcí dokument, jehož úkolem je vysvětlit, kde se v širším příběhu nacházejí dosud potvrzené body kontaktu, jaký je poměr rozsahu mezi prostorem OSKN a říší HELIOSU a kudy vedou nejdůležitější trasy, které v posledních etapách příběhu formovaly diplomatický i vojenský vývoj. Vizuálně zvýrazněný prostor HELIOSU záměrně působí výrazně větší než oblast OSKN. Právě nerovnoměrnost velikosti obou mocností patří mezi podstatné skutečnosti současného kánonu: HELIOS je mnohosvětová civilizace s obrovskými surovinovými a logistickými možnostmi, zatímco OSKN je menší, rychle rostoucí celek, jehož vliv stojí na technologii, vojenské odolnosti, organizaci a schopnosti integrovat nové lidi i druhy.</p>
<p>Na levé straně mapy leží Sluneční soustava. Je připomínkou vrstvy příběhu, v níž ještě dominovala původní lidská perspektiva, staré kolonie a technické limity před rozsáhlejším mezihvězdným kontaktem. Alpha Centauri funguje jako další orientační bod lidské expanze. Mezi starými oblastmi a novým centrem dnešního dění se nachází A7, označená jako jeden z prvních širších kontaktů s jinými civilizacemi. A7 je zároveň důležitá tím, že se později stala prvním nositelem funkčního prototypu nadprostorového pohonu 88/100. Mapa proto není jen soupisem míst. Každý bod připomíná konkrétní změnu ve schopnostech, vztazích nebo sebepojetí OSKN.</p>
<p>Nejdůležitějším uzlem modře vyznačené oblasti je Protos Singulár. Tento svět dnes představuje politické, průmyslové a kulturní srdce OSKN. Na jednom místě se zde setkávají lidé, Ursani, kočko-lidé, Vampirus, pso-lidé a další skupiny. Protos je tedy víc než domovská planeta: je důkazem, že projekt OSKN přerostl hranice původní posádky NII. Zároveň je logistickým bodem pro výrobu, správu, výzkum a obranu. V době Recensia získává jeho poloha ještě větší význam, protože Custodes sledují nejen jednotlivé lodě, ale i schopnost celé civilizace růst, organizovat průmysl a zacházet s poraženými protivníky.</p>
<p>Červené linie známých tras Vampirusu propojují mapu s další dějovou vrstvou. Vampirus byli dlouho vnímáni především jako hrozba a protivník, pozdější události však ukázaly složitější obraz. Záchrana přeživších z trosek nepřátelských lodí a přítomnost Adriany po boku Daniela Havla dokazují, že samotná příslušnost k druhu není v OSKN automatickým rozsudkem. Trasy na mapě proto připomínají jak nebezpečí, tak schopnost proměnit kontakt s nepřítelem v nový typ vztahu. V tomto smyslu jsou červené koridory stejně politické jako vojenské.</p>
<p>Modrý diplomatický koridor NII směřující k HELIOSU shrnuje možná největší proměnu posledního období. Z izolovaného přežívání a improvizovaného velení vzniklo strategické partnerství dvou civilizací. HELIOS poskytuje OSKN obrovské množství surovin, výrobních kapacit a logistické podpory. OSKN na oplátku dodává pokročilé vojenské technologie, ochranu a experimentální systémy. Aurelia na mapě představuje diplomatický a orbitální uzel tohoto vztahu. Nejde tedy jen o čáru spojující dva body. Je to tepna, po které se pohybují informace, technologie, lidé, dohody i politická důvěra.</p>
<p>Velké méně zmapované oblasti zůstávají záměrně prázdné. Databáze Rezerva tím nepředstírá úplnost. Naopak připomíná, že současný známý prostor je jen malou částí galaxie a že i civilizace s rozsáhlými flotilami a novými FTL technologiemi stále pracují s obrovskými mezerami v poznání. Praktická hodnota mapy je proto zároveň archivní: v jediné kompozici propojuje staré lidské výchozí body, novější uzly OSKN, rozlehlý blok HELIOSU a směry konfliktů, které definují poslední období. Je to mapa toho, co dnes víme, ale ještě víc mapa toho, kolik toho stále nevíme.</p>
<p>Pro běžného návštěvníka databáze má mapa ještě jednu důležitou funkci: ukazuje, jak dramaticky se změnilo měřítko příběhu. To, co kdysi bylo otázkou jedné posádky, jednoho doku a jedné porouchané korvety, je dnes otázkou celých civilizačních prostorů. Přesto mapa zachovává původní logiku projektu. Každá velká oblast je stále propojena s konkrétními lidmi, rozhodnutími a cestami. Právě proto zde vedle rozsáhlých říší zůstávají pojmenované body jako A7, Protos Singulár nebo Aurelia. Galaxie se zvětšila, ale příběh se stále skládá z míst, kde někdo musel učinit konkrétní rozhodnutí.</p>
</div></article>'''
insert('navigation',map_article,'article-galactic-map')

custodes_article='''
<article class="news-article" id="article-custodes-med"><span class="label red">OSKN MED // zvláštní zdravotnický záznam</span><h3>Pacientka Custodes Liminis na B4: když poražený protivník přestane být cílem a stane se pacientem</h3><p class="news-deck">Fotografie z oddělení OSKN MED zachycuje stabilizovanou příslušnici Custodes Liminis. Na první pohled klidná nemocniční scéna ve skutečnosti dokumentuje jednu z nejdůležitějších politických a morálních změn současného konfliktu.</p><div class="news-image lightbox"><img src="/assets/custodes-med-b4.png" alt="Stabilizovaná pacientka Custodes Liminis na oddělení OSKN MED B4" loading="lazy"><span class="caption">OSKN MED B4 // CUSTODES LIMINIS</span></div><div class="press-meta"><span class="hot">Custodes Liminis</span><span>OSKN MED B4</span><span>stabilizovaná</span><span>Recensio</span><span>ochrana přeživších</span></div><div class="news-body">
<p>Nový obrazový záznam z oddělení OSKN MED – B4 zachycuje jednu z nejdůležitějších proměn celého současného příběhu. Na první pohled jde o tichou nemocniční scénu: vysoká pacientka druhu Custodes Liminis sedí na lůžku v jednoduchém bílém nemocničním oděvu, vedle ní stojí zdravotnice OSKN a transparentní panel uvádí základní stavové informace. Ve skutečnosti však tento obraz shrnuje důsledek obrovského strategického zvratu. Custodes ještě nedávno představovaly civilizaci, která proti OSKN a HELIOSU zahájila Interdictio a pokusila se technologicky omezit jejich růst. Dnes je jedna z jejich příslušnic ošetřována nikoli jako trofej nebo experimentální materiál, ale jako pacientka chráněná pravidly zdravotní péče.</p>
<p>Právě tento rozdíl je zásadní. Po prvním skutečném střetu s Custodes bylo zachráněno dvanáct přeživších v kritickém stavu. Po pozdější bitvě u Caelum‑9 následovala druhá rozsáhlá záchranná operace a z vraků bylo vyproštěno dalších čtyřiapadesát příslušnic Custodes. Jednotky měly jednoduchá pravidla: ozbrojená přeživší dostane výzvu k odložení zbraně; pokud ji odloží, je chráněna a bude ošetřena. Popravy zajatých ani dorážení raněných nebyly povolené. Fotografie z B4 ukazuje, co toto pravidlo znamená v praxi po skončení střelby.</p>
<p>OSKN se tím vědomě odlišuje od logiky čisté odvety. Zachráněné Custodes nebyly podrobeny násilným výslechům ani experimentům s těly či implantáty. Lékaři je stabilizovali a přistupovali k nim jako k pacientkám. Tato skutečnost má přímý význam i pro probíhající Recensio. Custodes dlouhodobě předpokládaly, že rychle militarizovaná civilizace bude nevyhnutelně stále agresivnější a méně kontrolovatelná. OSKN jim však předkládá nepříjemný rozpor: současně masově vyrábí Protectory V52, vyvíjí nové FTL technologie a parakauzální zbraně, ale zároveň zachraňuje poražené nepřátele a poskytuje jim léčbu.</p>
<p>Obraz vypovídá něco i o Custodes samotných. V předchozích záznamech se objevovaly hlavně jako vzdálení pozorovatelé, arbitři a technologicky dominantní síla, která po tisíce let hodnotí jiné civilizace podle vlastního Limenu. Zde je jejich příslušnice zobrazena opačně: zranitelná, unavená a odkázaná na péči těch, které její civilizace označila za problém. Tím se konflikt přestává jevit jako abstraktní výměna salv mezi ikonami flotil a dostává lidsky čitelný rozměr. Nepřítel má tvář, tělo a zdravotní stav.</p>
<p>Dalším důležitým prvkem je otevřenost záznamu. Digitální karta vedle lůžka uvádí příslušnost Custodes Liminis, pohlaví, výšku, stav stabilizace i oddělení OSKN MED. Databáze tak neskrývá, že OSKN léčí členku civilizace, která proti němu vedla vojenskou operaci. To není slabost systému, ale demonstrace jeho disciplíny. Pravidla nemají platit jen tehdy, když je jejich dodržování snadné. Právě v zacházení s poraženým protivníkem se ukazuje, jestli ochranná doktrína existuje skutečně, nebo jen jako slogan.</p>
<p>Fotografie z B4 proto patří mezi strategicky významné dokumenty stejně jako záznamy bitev. Ukazuje civilizaci, která dokáže extrémně tvrdě bojovat a současně zastavit násilí ve chvíli, kdy protivník přestane být bezprostřední hrozbou. Pro Custodes, jejichž staré modely spojují vojenský růst s narůstající agresivitou, je takový obraz možná stejně problematický jako samotný Protector V52. A pro OSKN představuje připomínku, že skutečná síla se neměří jen tím, co dokáže zničit, ale také tím, koho dokáže zachránit, když už bitva skončila.</p>
<p>Význam této péče navíc nekončí stabilizací životních funkcí. Daniel pacientky navštěvuje, komunikuje s nimi a přináší jim knihy, ovoce, seriály a stolní hry. Tím se nemocniční oddělení mění i v první skutečný prostor kulturního kontaktu. Custodes zde postupně poznávají OSKN jinak než skrze senzory a bojové modely. Zdravotnická péče se tak stává nejen otázkou etiky, ale i prvním mostem, který může v budoucnu změnit samotný výsledek Recensia.</p>
</div></article>'''
insert('intel',custodes_article,'article-custodes-med')

diplomacy='''
<article class="news-article" id="article-diplomacy-third"><span class="label green">diplomatická analýza // třetí článek</span><h3>Dvě civilizace, jeden tlak: proč spojenectví OSKN a HELIOSU mění význam Recensia</h3><p class="news-deck">HELIOS je větší, OSKN rychlejší v některých vojenských a experimentálních směrech. Custodes však během Recensia nesledují dva oddělené státy. Sledují vznikající systém, v němž logistická hloubka jednoho partnera zesiluje technologickou odvahu druhého.</p><div class="press-meta"><span class="hot">OSKN × HELIOS</span><span>Delta 7</span><span>Daniel Havel</span><span>strategické partnerství</span><span>Recensio</span></div><div class="news-body">
<p>Vztah mezi OSKN a říší HELIOSU už nelze popsat jako obyčejnou dohodu dvou sousedů. HELIOS je rozsáhlá mnohosvětová civilizace s výrazně větší populační, průmyslovou a logistickou základnou. OSKN je proti němu menší, ale během krátké doby prokázalo mimořádnou schopnost soustředit zdroje, improvizovat a převádět zkušenosti z krizí do nových technologií. Právě spojení těchto odlišných vlastností vytvořilo partnerství, které Custodes Liminis nedokážou snadno zařadit do svých historických modelů. Recensio proto dnes nehodnotí jen jednu novou mocnost. Ve skutečnosti hodnotí vztah, jehož možnosti mohou být větší než prostý součet obou stran.</p>
<p>HELIOS poskytuje OSKN suroviny, výrobní kapacity a logistickou podporu v rozsahu, kterého by menší OSKN samo dosahovalo podstatně pomaleji. OSKN na oplátku přináší pokročilé vojenské technologie, ochranu, experimentální systémy a zkušenost s rychlou adaptací na nepředvídatelné protivníky. Tento výměnný model je důležitý, protože odstraňuje tradiční slabiny obou partnerů. OSKN nemusí všechny projekty stavět na omezeném průmyslovém základu. HELIOS zase nemusí každou novou hrozbu řešit pouze vlastními dlouhodobými vývojovými procesy.</p>
<p>Osobní rovina vztahu má rovněž význam. Delta 7 a Daniel Havel se postupně stali blízkými přáteli a strategickými partnery. Databáze tuto skutečnost neinterpretuje jako formální podřízení jedné říše druhé. Naopak jde o vztah, který zatím stojí na vzájemné důvěře a společném zájmu. To je podstatné zejména ve chvíli, kdy Custodes očekávají, že tlak zvenčí vyvolá rozklad, izolacionismus nebo soupeření o zdroje. Dosavadní vývoj ukázal opak: tlak Interdictia přiměl oba celky ke koordinaci.</p>
<p>Bitva u Caelum‑9 tuto skutečnost předvedla názorně. Custodes napadly prostor HELIOSU, ale odpověď nebyla čistě helioská. Do soustavy bylo vysláno třicet Protectorů V52 a dorazila také NII. Výsledek ukázal, že hranice politického prostoru nemusí odpovídat hranici obranné odpovědnosti. Jestliže je HELIOS napaden, OSKN situaci nevnímá jen jako cizí problém. Právě tato schopnost rychlé společné reakce mění strategický význam partnerství víc než jakýkoli slavnostní text smlouvy.</p>
<p>Recensio se tím dostává do paradoxní situace. Původním cílem custodského tlaku bylo zpomalit nebo zastavit technologie třídy Limen. Místo toho se během sledovaného období rozšířila výroba Protectorů až na 130 dokončených kusů, vznikly nové FTL koncepty a do vývoje byly zapojeny další druhy a skupiny z obou civilizačních prostorů. Custodský tlak tak nepřímo zvýšil motivaci ke spolupráci. Čím větší je vnější hrozba, tím větší význam získává logistická hloubka HELIOSU a technologická pružnost OSKN.</p>
<p>Spolupráce se navíc neomezuje na vojenskou výrobu. Mnohodruhové prostředí HELIOSU a stále pestřejší společnost OSKN vytvářejí prostor pro výměnu zkušeností mezi lidmi, elfy, temnými elfy, trpaslíky, pso-lidmi, mrazivými obry a dalšími skupinami. Nové technologie proto nevznikají jen v jediné národní laboratoři. Stávají se výsledkem kombinace různých kultur a způsobů myšlení. Pro civilizaci Custodes, která tisíce let pracuje s vlastními historickými kategoriemi, může být právě tato síť spolupráce obtížně předvídatelná.</p>
<p>To však neznamená, že spojenectví musí být bez rizik. Rozdílná velikost, odlišné kultury a asymetrie zdrojů mohou v budoucnu vytvářet politické otázky, které dnešní válečný tlak zatím překrývá. Právě proto je důležité, aby Databáze Rezerva vztah neprezentovala jako automatické sjednocení. HELIOS zůstává HELIOSem a OSKN zůstává OSKN. Síla jejich spolupráce spočívá právě v tom, že dvě samostatné civilizace dokážou sdílet schopnosti bez nutnosti ztratit vlastní identitu. V době Recensia je to možná jejich největší strategická výhoda — a současně další důvod, proč staré modely Custodes přestávají fungovat.</p>
</div></article>'''
